Use a pasta da lição 3. Troque o server.js por esta versão, que só conta se recebeu a senha (sem mostrá-la):
const express = require("express");
const app = express();
const hasPassword = Boolean(process.env.DB_PASSWORD);
app.get("/", (req, res) => res.send("Olá da marmitaria! Senha recebida: " + hasPassword + "\n"));
app.listen(3000, () => console.log("ouvindo na porta 3000"));
E crie um .env de mentira, como o do estagiário:
DB_PASSWORD=marmita123
